/// Variant B of every key (different sample arguments).
/// Parameterized keys must render differently across variants:
/// that proves the placeholder survived translation.
String? _valueB(ComponentLocalizations l, String key) {
  return switch (key) {
    'formLessThan' => l.formLessThan(7),
    'formGreaterThan' => l.formGreaterThan(7),
    'formLessThanOrEqualTo' => l.formLessThanOrEqualTo(7),
    'formGreaterThanOrEqualTo' => l.formGreaterThanOrEqualTo(7),
    'formEqualTo' => l.formEqualTo(7),
    'formBetweenInclusively' => l.formBetweenInclusively(2, 6),
    'formBetweenExclusively' => l.formBetweenExclusively(2, 6),
    'formLengthLessThan' => l.formLengthLessThan(5),
    'formLengthGreaterThan' => l.formLengthGreaterThan(5),
