void main() {
  final Map<String, Map<String, String>> report =
      <String, Map<String, String>>{};

  for (final MapEntry<String, Locale> entry in kRequiredLocales.entries) {
    final String code = entry.key;
    final ComponentLocalizations strings = lookupComponentLocalizations(
      entry.value,
    );
    test('locale $code carries every key', () {
      final Map<String, String> row = <String, String>{};
      for (final String key in kLocaleKeys) {
        final String a = _valueA(strings, key);
        expect(a.isNotEmpty, isTrue, reason: '$code/$key is empty');
        final String? b = _valueB(strings, key);
        if (b != null) {
          expect(
            b != a,
            isTrue,
            reason: '$code/$key drops its placeholder ($a)',
          );
        }
        row[key] = a;
      }
      report[code] = row;
    });

    test('locale $code overrides every key in source', () {
      final String path =
          'lib/src/primitives/localizations/localizations_${_fileSuffix(code)}.dart';
      final String src = File(path).readAsStringSync();
      final List<String> missing = <String>[];
      // Dispatchers: covered at runtime; they read the overridden leaves.
      const Set<String> dispatchers = <String>{
        'getAbbreviatedWeekday',
        'getMonth',
        'getAbbreviatedMonth',
      };
      for (final String key in kLocaleKeys) {
        if (dispatchers.contains(key)) {
          continue;
        }
        final bool getter = src.contains('String get $key =>');
        final bool method = src.contains('String $key(');
        if (!getter && !method) {
          // Inherited tables (pt-BR from pt, zh-Hans from zh) may carry the
          // override on the parent; check there before failing.
          final String? parent = switch (code) {
            'pt-BR' => 'lib/src/primitives/localizations/localizations_pt.dart',
            'zh-Hans' =>
              'lib/src/primitives/localizations/localizations_zh.dart',
            _ => null,
          };
          if (parent == null ||
              !File(parent).readAsStringSync().contains(
                RegExp('String (get $key|$key\\()'),
              )) {
            missing.add(key);
          }
        }
      }
      expect(missing, isEmpty, reason: '$code missing: ${missing.join(', ')}');
    });
  }

  test('write LOCALE_REPORT.md', () {
    final StringBuffer out = StringBuffer();
    out.writeln('# LOCALE_REPORT — per-key completeness per required locale');
    out.writeln();
    out.writeln(
      'Generated by `dashcn/test/registry/i18n_locale_completeness_test.dart`.',
    );
    out.writeln('Every cell is a passing assertion: the key is overridden in');
    out.writeln(
      'the locale source (or an inherited parent), renders non-empty,',
    );
    out.writeln('and parameterized keys interpolate their arguments.');
    out.writeln();
    out.writeln('| locale | keys | direction |');
    out.writeln('|---|---|---|');
    const Map<String, String> direction = <String, String>{
      'ar': 'RTL',
      'he': 'RTL',
      'fa': 'RTL',
      'ur': 'RTL',
    };
    for (final String code in kRequiredLocales.keys) {
      out.writeln(
        '| $code | ${kLocaleKeys.length}/${kLocaleKeys.length} | ${direction[code] ?? 'LTR'} |',
      );
    }
    out.writeln();
    out.writeln('## Notes');
    out.writeln();
    out.writeln(
      '- `pt-BR` subclasses the `pt` table and overrides only the strings',
    );
    out.writeln(
      '  where Brazilian usage differs; every other key is inherited.',
    );
    out.writeln(
      '- `zh-Hans` pins the `Hans` script subtag onto the simplified `zh`',
    );
    out.writeln('  table; every key is inherited.');
    out.writeln(
      '- Numbers use `intl` decimal patterns per locale (`_number`); Arabic',
    );
    out.writeln('  renders Arabic-Indic digits, which the placeholder check');
    out.writeln('  tolerates by comparing two distinct arguments.');
    final File report = File('LOCALE_REPORT.md');
    report.writeAsStringSync(out.toString());
  });
}
